require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><main class="main"><header class="topbar"><h1>Verifiche</h1><div class="user-menu"><a href="logout.php">Esci</a></div></header><section class="content"><div class="page-head"><h2>Verifiche e scadenze</h2><p>Calendario delle attività programmate per la tua classe.</p></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Materia</th><th>Descrizione</th><th>Stato</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="4" class="empty">Nessuna verifica programmata.</td></tr><?php endif;foreach($rows as $r): ?><tr><td><?=date('d/m/Y',strtotime($r['data']))?></td><td><?=e($r['materia'])?></td><td><?=e($r['descrizione'])?></td><td class="<?=$r['data']>=$oggi?'good':'muted'?>"><?=$r['data']>=$oggi?'In arrivo':'Conclusa'?></td></tr><?php endforeach?></tbody></table></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>